"use client"

import { useParams } from "next/navigation"
import { Button } from "@/components/ui/button"
import { ChildDetailModal } from "@/components/parent/child-detail-modal"
import { ChevronLeft } from "lucide-react"
import Link from "next/link"
import { ParentSidebar } from "@/components/layout/parent-sidebar"

// Mock children data
const childrenData: Record<number, { name: string; age: number; grade: string }> = {
  1: { name: "Emma Johnson", age: 8, grade: "2nd" },
  2: { name: "Noah Johnson", age: 10, grade: "4th" },
  3: { name: "Sophie Johnson", age: 7, grade: "1st" },
}

export default function ChildDetailPage() {
  const params = useParams()
  const childId = Number(params.id)
  const child = childrenData[childId]

  if (!child) {
    return (
      <div className="md:flex h-screen">
        <ParentSidebar />
        <div className="flex-1 p-6">
          <div className="text-center py-12">
            <p className="text-muted-foreground">Child not found.</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="md:flex h-screen">
      <ParentSidebar />
      <div className="flex-1 overflow-auto">
        <div className="p-6">
          <Link href="/parent-dashboard/children">
            <Button variant="ghost" className="gap-2 mb-6">
              <ChevronLeft className="w-5 h-5" />
              Back to Children
            </Button>
          </Link>

          <ChildDetailModal childId={childId} name={child.name} age={child.age} grade={child.grade} />
        </div>
      </div>
    </div>
  )
}
